@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@rendermode InteractiveWebAssembly
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h3 class="mb-4">Shipment Dashboard</h3>

<div class="row mb-3">
    <div class="col-md-4">
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="selectedStatus">
            <option value="">All</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-4">
        <label class="form-label">Search</label>
        <input type="text" class="form-control" placeholder="Tracking # or destination..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4 d-flex align-items-end">
        <button class="btn btn-primary" @onclick="LoadShipments">
            <span class="bi bi-arrow-clockwise"></span> Refresh
        </button>
    </div>
</div>

@if (loading)
{
    <div class="d-flex justify-content-center my-4">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (FilteredShipments.Count == 0)
{
    <div class="alert alert-info">No shipments found matching your criteria.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th @onclick='() => SortBy("TrackingNumber")' style="cursor:pointer">
                        Tracking # @SortIndicator("TrackingNumber")
                    </th>
                    <th @onclick='() => SortBy("Destination")' style="cursor:pointer">
                        Destination @SortIndicator("Destination")
                    </th>
                    <th @onclick='() => SortBy("Status")' style="cursor:pointer">
                        Status @SortIndicator("Status")
                    </th>
                    <th @onclick='() => SortBy("EstimatedDelivery")' style="cursor:pointer">
                        Est. Delivery @SortIndicator("EstimatedDelivery")
                    </th>
                    <th>Customer</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Destination</td>
                        <td>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">
                                @shipment.Status
                            </span>
                        </td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>@shipment.CustomerName</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@shipment.Status"
                                    @onchange="(e) => UpdateStatus(shipment, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @FilteredShipments.Count of @shipments.Count shipments</p>
}

@code {
    private List<Shipment> shipments = [];
    private bool loading = true;
    private string selectedStatus = "";
    private string searchTerm = "";
    private string sortColumn = "EstimatedDelivery";
    private bool sortAscending = true;

    private List<Shipment> FilteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(selectedStatus) || s.Status.ToString() == selectedStatus)
        .Where(s => string.IsNullOrEmpty(searchTerm) ||
                    s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                    s.CustomerName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
        .OrderBy(s => sortColumn switch
        {
            "TrackingNumber" => (object)(sortAscending ? s.TrackingNumber : ""),
            "Destination" => sortAscending ? s.Destination : "",
            "Status" => sortAscending ? (int)s.Status : 0,
            "EstimatedDelivery" => sortAscending ? s.EstimatedDelivery.Ticks : 0,
            _ => s.EstimatedDelivery.Ticks
        })
        .ThenByDescending(s => sortColumn switch
        {
            "TrackingNumber" => (object)(sortAscending ? "" : s.TrackingNumber),
            "Destination" => sortAscending ? "" : s.Destination,
            "Status" => sortAscending ? 0 : (int)s.Status,
            "EstimatedDelivery" => sortAscending ? 0 : s.EstimatedDelivery.Ticks,
            _ => 0
        })
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private string SortIndicator(string column)
    {
        if (sortColumn != column) return "";
        return sortAscending ? "▲" : "▼";
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveWebAssembly
@inject IShipmentService ShipmentService

<PageTitle>Track Your Shipment</PageTitle>

<h3 class="mb-4">Track Your Shipment</h3>

<div class="row justify-content-center">
    <div class="col-md-8">
        <div class="input-group mb-4">
            <input type="text" class="form-control form-control-lg"
                   placeholder="Enter tracking number (e.g., SHP-001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@searching">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Track
            </button>
        </div>

        @if (searched && shipment == null)
        {
            <div class="alert alert-warning">
                <strong>Not found.</strong> No shipment matches tracking number "<strong>@lastSearched</strong>".
                Please verify the number and try again.
            </div>
        }

        @if (shipment != null)
        {
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <h5 class="mb-0">
                        <code>@shipment.TrackingNumber</code>
                    </h5>
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">
                        @shipment.Status
                    </span>
                </div>
                <div class="card-body">
                    <div class="row mb-3">
                        <div class="col-sm-6">
                            <strong>Origin:</strong>
                            <p>@shipment.Origin</p>
                        </div>
                        <div class="col-sm-6">
                            <strong>Destination:</strong>
                            <p>@shipment.Destination</p>
                        </div>
                    </div>
                    <div class="row mb-3">
                        <div class="col-sm-6">
                            <strong>Shipped Date:</strong>
                            <p>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                        </div>
                        <div class="col-sm-6">
                            <strong>Estimated Delivery:</strong>
                            <p class="fw-bold text-primary">@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                        </div>
                    </div>
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <div class="row mb-3">
                            <div class="col-sm-6">
                                <strong>Actual Delivery:</strong>
                                <p class="text-success fw-bold">@shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</p>
                            </div>
                        </div>
                    }
                    <div class="row mb-3">
                        <div class="col-sm-6">
                            <strong>Description:</strong>
                            <p>@shipment.Description</p>
                        </div>
                        <div class="col-sm-6">
                            <strong>Weight:</strong>
                            <p>@shipment.WeightKg.ToString("F1") kg</p>
                        </div>
                    </div>

                    <!-- Progress visualization -->
                    <hr />
                    <h6>Shipment Progress</h6>
                    <div class="progress mb-2" style="height: 25px;">
                        <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                             role="progressbar"
                             style="width: @(GetProgressPercent(shipment.Status))%"
                             aria-valuenow="@GetProgressPercent(shipment.Status)"
                             aria-valuemin="0" aria-valuemax="100">
                            @shipment.Status
                        </div>
                    </div>
                    <div class="d-flex justify-content-between text-muted small">
                        <span>Pending</span>
                        <span>Picked Up</span>
                        <span>In Transit</span>
                        <span>Out for Delivery</span>
                        <span>Delivered</span>
                    </div>
                </div>
            </div>
        }
    </div>
</div>

@code {
    private string trackingNumber = "";
    private string lastSearched = "";
    private Shipment? shipment;
    private bool searching;
    private bool searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        searched = false;
        shipment = null;

        shipment = await ShipmentService.GetByTrackingNumberAsync(trackingNumber.Trim());
        lastSearched = trackingNumber.Trim();
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        ShipmentStatus.Returned => 100,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-primary"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

