using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
    }

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        return await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    }

    public async Task<List<Shipment>> GetShipmentsByStatusAsync(ShipmentStatus? status)
    {
        var query = db.Shipments.AsQueryable();
        if (status.HasValue)
            query = query.Where(s => s.Status == status.Value);
        return await query.OrderByDescending(s => s.ShippedDate).ToListAsync();
    }

    public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment != null)
        {
            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;
            await db.SaveChangesAsync();
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async ([FromQuery] ShipmentStatus? status, IShipmentService service) =>
        {
            if (status.HasValue)
                return Results.Ok(await service.GetShipmentsByStatusAsync(status));
            return Results.Ok(await service.GetAllShipmentsAsync());
        });

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapPut("/{id:int}/status", async (int id, [FromBody] ShipmentStatus newStatus, IShipmentService service) =>
        {
            await service.UpdateStatusAsync(id, newStatus);
            return Results.NoContent();
        }).RequireAuthorization();
    }
}

